using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using MyFundex.BuildingBlocks.Abstractions;using MyFundex.BuildingBlocks.Domain;using MyFundex.BuildingBlocks.Persistence;using MyFundex.Contracts;
namespace MyFundex.Notifications;
public sealed class Notification:EntityBase{public Guid NotificationId{get;set;}public long UserInternalId{get;set;}public string Type{get;set;}="General";public string Title{get;set;}="";public string Message{get;set;}="";public bool IsRead{get;set;}public DateTimeOffset? ReadAt{get;set;}}
public sealed class NotificationDbContext(DbContextOptions<NotificationDbContext>o,ICurrentActor a):AuditableDbContext(o,a){public DbSet<Notification>Notifications=>Set<Notification>();protected override void OnModelCreating(ModelBuilder m){m.HasDefaultSchema("notification");ConfigureEntity(m.Entity<Notification>());m.Entity<Notification>().HasIndex(x=>x.NotificationId).IsUnique();m.Entity<Notification>().HasIndex(x=>new{x.UserInternalId,x.IsRead});}}
public sealed class NotificationSender(NotificationDbContext db):INotificationSender{public async Task CreateAsync(long userId,string type,string title,string message,CancellationToken ct){db.Add(new Notification{NotificationId=MyFundex.BuildingBlocks.Ids.Uuid7.NewGuid(),UserInternalId=userId,Type=type,Title=title,Message=message});await db.SaveChangesAsync(ct);}}
public static class NotificationsModule{public static IServiceCollection AddNotificationsModule(this IServiceCollection s,string cs){s.AddDbContext<NotificationDbContext>(o=>o.UseNpgsql(cs));s.AddScoped<INotificationSender,NotificationSender>();return s;}}
